package com.pethop.report;
import com.pethop.pet.Pet; import com.pethop.user.User; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import org.hibernate.annotations.UuidGenerator;
@Entity @Table(name="user_reports") public class UserReport{
 @Id @UuidGenerator private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="reporter_id",nullable=false)private User reporter; @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="pet_id",nullable=false)private Pet pet;
 @Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private ReportCategory category; @Column(nullable=false,columnDefinition="text")private String description; @Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ReportStatus status=ReportStatus.SUBMITTED; @Column(name="resolution_details",columnDefinition="text")private String resolutionDetails; @ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="resolved_by")private User resolvedBy; @Column(name="resolved_at")private Instant resolvedAt; @Column(name="created_at",nullable=false,updatable=false)private Instant createdAt; @PrePersist void onCreate(){createdAt=Instant.now();}
 public UUID getId(){return id;} public User getReporter(){return reporter;}public void setReporter(User v){reporter=v;}public Pet getPet(){return pet;}public void setPet(Pet v){pet=v;}public ReportCategory getCategory(){return category;}public void setCategory(ReportCategory v){category=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public ReportStatus getStatus(){return status;}public void setStatus(ReportStatus v){status=v;}public String getResolutionDetails(){return resolutionDetails;}public void setResolutionDetails(String v){resolutionDetails=v;}public User getResolvedBy(){return resolvedBy;}public void setResolvedBy(User v){resolvedBy=v;}public Instant getResolvedAt(){return resolvedAt;}public void setResolvedAt(Instant v){resolvedAt=v;}public Instant getCreatedAt(){return createdAt;}
}
